sys_script_include.script:
var BaseUtils = Class.create();
BaseUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    /**
     * Esta é a nossa ÚNICA função de validação.
     * Ela verifica todas as regras de duplicidade da tabela Base de uma só vez.
     */
    validateBaseSubmit: function() {
        // Pegar todos os parâmetros do formulário
		var managerSysId = this.getParameter('sysparm_manager_sysid');
		var name = this.getParameter('sysparm_base_name'); // <-- ESTA É A LINHA QUE MUDAMOS
		var city = this.getParameter('sysparm_city');
		var state = this.getParameter('sysparm_state');
		var currentSysId = this.getParameter('sysparm_current_base_sysid');

        // --- ATENÇÃO: Verifique os nomes da sua tabela e campos abaixo ---
        var tableName = 'x_1836079_office_base'; // <-- NOME DA SUA TABELA BASE
        var managerField = 'manager_base';        // <-- NOME DO CAMPO GERENTE
        var nameField = 'name';                   // <-- NOME DO CAMPO NOME
        var cityField = 'city';                   // <-- NOME DO CAMPO CIDADE
        var stateField = 'state';                 // <-- NOME DO CAMPO ESTADO

        // --- 1. Validação do Gerente (História 2) ---
        if (managerSysId) {
            var grManager = new GlideRecord(tableName); 
            grManager.addQuery(managerField, managerSysId); 
            if (currentSysId) grManager.addQuery('sys_id', '!=', currentSysId);
            grManager.query();
            if (grManager.next()) {
                return 'ERR_DUPE_MANAGER'; // Erro: Gerente duplicado
            }
        }

        // --- 2. Validação do Nome (História 4a) ---
        if (name) {
            var grName = new GlideRecord(tableName);
            grName.addQuery(nameField, name);
            if (currentSysId) grName.addQuery('sys_id', '!=', currentSysId);
            grName.query();
            if (grName.next()) {
                return 'ERR_DUPE_NAME'; // Erro: Nome duplicado
            }
        }

        // --- 3. Validação de Cidade+Estado (História 4b) ---
        if (city && state) {
            var grLocation = new GlideRecord(tableName);
            grLocation.addQuery(cityField, city); 
            grLocation.addQuery(stateField, state); 
            if (currentSysId) grLocation.addQuery('sys_id', '!=', currentSysId);
            grLocation.query();
            if (grLocation.next()) {
                return 'ERR_DUPE_LOCATION'; // Erro: Localização duplicada
            }
        }

        // --- 4. Se passou em tudo ---
        return 'VALID'; // Resposta: Tudo OK!
    },

    /* ** Nova função para a H13 (Validação de Lotação no Formulário)
** Esta função calcula a lotação (H11) e a lotação máxima
*/
	checkBaseOccupancy: function() {
		var baseId = this.getParameter('sysparm_base_id');
		var response = {
			current: 0,
			max: 0
		};

		// 1. Buscar a Lotação Máxima da Base
		var grBase = new GlideRecord('x_1836079_office_base'); // Sua tabela de Base
		if (grBase.get(baseId)) {
			response.max = parseInt(grBase.getValue('max_capacity')) || 0;
		}

		// 2. Calcular a Lotação Atual (H11: Aprovados + Pendentes)
		var ESTADO_APROVADO = '3';
		var ESTADO_PENDENTE = '2';

		var ga = new GlideAggregate('x_1836079_office_registration'); // Sua tabela de Inscrição
		ga.addQuery('base', baseId);
		ga.addEncodedQuery('state=' + ESTADO_APROVADO + '^ORstate=' + ESTADO_PENDENTE);
		ga.addAggregate('COUNT');
		ga.query();

		if (ga.next()) {
			response.current = parseInt(ga.getAggregate('COUNT'));
		}

		// 3. Retornar os dois números
		// --- A CORREÇÃO ESTÁ AQUI ---
		// Errado: var json = new JSON(); return json.encode(response);
		// Certo: Usar o método estático JSON.stringify()
		return JSON.stringify(response);
},

	type: 'BaseUtils'
});
